R/: S4 classes, a short example
Before creating a new class, check whether an existing one can hold your data (or be extended). If you do need one:

setClass("CountSet",
    slots = c(counts = "matrix", condition = "factor"),
    validity = function(object) {
        if (ncol(object@counts) != length(object@condition))
            return("ncol(counts) must equal length(condition)")
        TRUE
    }
)

## A constructor (users never call new() directly)
CountSet &lt;- function(counts, condition) {
    new("CountSet", counts = counts, condition = factor(condition))
}

tests/: writing unit tests with {testthat}
usethis::use_testthat()               # tests/testthat.R + tests/testthat/
usethis::use_test("normalizeCounts")  # tests/testthat/test-normalizeCounts.R


## Toy data: 3 genes x 2 samples
counts &lt;- matrix(c(10, 0, 5, 20, 3, 7), nrow = 3)

test_that("normalizeCounts() returns CPM values", {
    cpm &lt;- normalizeCounts(counts, method = "cpm")

    expect_true(is.matrix(cpm))
    expect_equal(dim(cpm), dim(counts))
    expect_equal(unname(colSums(cpm)), c(1e6, 1e6))
})

test_that("normalizeCounts() throws errors for invalid input", {
    expect_error(normalizeCounts(as.data.frame(counts)), "numeric matrix")
    expect_error(normalizeCounts(-counts), "negative")
})

